using System.Linq; using common.resources; using wServer.realm.entities;
namespace wServer.realm.worlds.logic { class AshenFoundry:World { Enemy sun; int vents; bool done; public AshenFoundry(ProtoWorld p):base(p){DungeonAnomalyService.Attach(this,DungeonAnomalyService.Roll(DungeonCodexService.All.FirstOrDefault(x=>x.Key=="AshenFoundry"),new System.Random(Id)));} public override int EnterWorld(Entity e){var id=base.EnterWorld(e);var n=e as Enemy;if(n==null)return id;n.OnDeath+=(s,a)=>Dead(n);if(n.ObjectDesc.ObjectId=="The Iron Sun"){sun=n;sun.ApplyConditionEffect(ConditionEffectIndex.Invincible);}return id;} void Dead(Enemy e){if(e.ObjectDesc.ObjectId=="Heat Vent"&&++vents>=3&&sun!=null)sun.ApplyConditionEffect(ConditionEffectIndex.Invincible,0);if(e.ObjectDesc.ObjectId=="The Iron Sun"&&!done){done=true;DungeonAnomalyService.Cleanup(this);foreach(var p in Players.Values)p.SendInfo("Ashen Foundry cleared.");}}} }
